function cor = checkFix(td)global scr visual constif const.TEST>1    cor = 1;else    timeout = 1.00; % maximum fixation check time    tCorMin = 0.20; % minimum correct fixation time        % determine recorded eye    if ~isfield(const,'DOMEYE') && ~const.TEST        evt = Eyelink('newestfloatsample');        const.DOMEYE = find(evt.gx ~= -32768);        const.DOMEYE = max(const.DOMEYE);    end        cxm = td.fixa.loc(1);    cym = td.fixa.loc(2);    rad = visual.fixCkRad;        if ~const.TEST        Eyelink('command','draw_box %d %d %d %d 15', (cxm-rad)*2, (cym-rad)*2, (cxm+rad)*2, (cym+rad)*2);    else        % SetMouse(cxm,cym);%,scr.expScreen);    end        for f = 1:scr.rate        drawFixation(visual.fixCkCol,td.fixa.loc);        drawGoSignal(visual.fixCkCol,td.fixa.loc);        PsychProPixx('QueueImage', scr.myimg);    end    Eyelink('message', 'EVENT_FixationCheck');        tstart=GetSecs;    cor=0;corStart=0;tCor=0;    t=tstart;    while ((t-tstart) < timeout && tCor<=tCorMin)        [x,y] = getCoord;        if sqrt((x-cxm)^2+(y-cym)^2)<rad            cor = 1;        else            cor = 0;        end        if cor == 1 && corStart == 0            tCorStart = GetSecs;            corStart = 1;        elseif cor == 1 && corStart == 1            tCor = GetSecs-tCorStart;        else            corStart = 0;        end                t=GetSecs;    endend